296	     * @return the lower-cased email, or {@code null} if none was supplied
297	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
298	     *                                     yielding a 400 response
299	     */
300	    private String normalizeEmail(String email) {
301	        if (email == null) {
302	            return null;
303	        }
304	        if (!EMAIL_PATTERN.matcher(email).matches()) {
305	            throw new InvalidOwnerFieldsException(List.of("email"));
306	        }
307	        return email.toLowerCase(Locale.ROOT);
308	    }
