310	    /**
311	     * Rejects creation of an owner whose normalized telephone is already used by any other owner.
312	     * Stored telephones are normalized here as well so the comparison is independent of the format
313	     * each owner was originally saved with.
314	     *
315	     * @param telephone the normalized telephone of the owner being created
316	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
317	     *                                          yielding a 409 Conflict response
318	     */
319	    private void rejectDuplicateTelephone(String telephone) {
320	        boolean inUse = this.clinicService.findAllOwners().stream()
321	            .map(Owner::getTelephone)
322	            .map(this::digitsOnly)
323	            .anyMatch(telephone::equals);
324	        if (inUse) {
325	            throw new DuplicateOwnerTelephoneException(telephone);
326	        }
327	    }
